fn create_row(n: u8) -> Vec<u8> {
    // Pre-allocate a Vec of length n (as usize) to avoid reallocations.
    let mut row = Vec::with_capacity(n as usize);
    // Fill it with 0, 1, 2, ..., n-1.
    for i in 0u8..n {
        row.push(i);
    }
    row
}

fn indices(n: u8) -> Vec<Vec<u8>> {
    // The grid is a Vec containing exactly one row.
    vec![create_row(n)]
}

